        "steps": [
          {
            "id": "a0000000-0000-4000-8000-000000000940",
            "name": "Initial need",
            "summary": "A tutor needs to come off a session, and the app routes them to the right flow: a one-time call-off, a recurring withdrawal, or a swap.",
            "position": 1
          },
          {
            "id": "a0000000-0000-4000-8000-000000000941",
            "name": "Files call-off (12h+, auto-approved)",
            "summary": "The tutor files a one-time call-off twelve or more hours ahead; the rules auto-approve it and supervisors take no action.",
            "position": 2
          },
          {
            "id": "a0000000-0000-4000-8000-000000000943",
            "name": "Coverage via fill-in pool",
            "summary": "Coverage is automatic: the freed slot appears in every other tutor's Fill-In tab.",
            "position": 3
          },
          {
            "id": "a0000000-0000-4000-8000-000000000944",
            "name": "Supervisor review (pending/excuse)",
            "summary": "Supervisors review the pending call-offs and record the excused or unexcused decision.",
            "position": 4
          },
          {
            "id": "a0000000-0000-4000-8000-000000000945",
            "name": "Final notification",
            "summary": "The tutor receives the excused or unexcused decision in the app.",
            "position": 5
          },
          {
            "id": "a0000000-0000-4000-8000-000000000942",
            "name": "Files late call-off (<12h, immediate removal)",
            "summary": "The tutor files inside twelve hours; removal from the roster is immediate and review decides whether it counts as excused.",
            "position": 6
          }
        ],
