        "steps": [
          {
            "id": "a0000000-0000-4000-8000-000000000960",
            "name": "Students join",
            "summary": "Students arrive in Zoom and the lead tutor greets them; placeSingleStudent slots each new arrival onto a tutor, who sees them appear on their assignment list.",
            "position": 1
          },
          {
            "id": "a0000000-0000-4000-8000-000000000961",
            "name": "Share screen and log in",
            "summary": "The teacher asks students to share their screen and log into the math software; the tutor confirms it and the lead tutor mutes where needed.",
            "position": 2
          },
          {
            "id": "a0000000-0000-4000-8000-000000000962",
            "name": "Raise hand for help",
            "summary": "The teacher shows students the raise-hand emoji; tutors move their students into breakout rooms and the lead tutor pings anyone whose late joiner is still waiting.",
            "position": 3
          }
        ],
